import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/BDM.scaBLLhv.js";import{_ as o,a as i,b as s,c as r,d as n,e as l,f as d}from"./chunks/M-SS-NFcert.CC0MK3SI.js";import{_ as c}from"./chunks/M-SS.C4V7iNpZ.js";import{_ as h,o as p,c as u,a3 as m}from"./chunks/framework.g9mfNVRQ.js";const N=JSON.parse('{"title":"System Status","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshoot/systemstatus.md","filePath":"troubleshoot/systemstatus.md"}'),g={name:"troubleshoot/systemstatus.md"};function f(b,e,y,v,w,_){return p(),u("div",null,[...e[0]||(e[0]=[m('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> System Status</p></div><p>System status provides internal information on xDrip collector state (either from a sensor or as a follower) as well as sharing, followers and smartwatch connected directly.</p><p>You can share a screenshot with the Android share button top right.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;">System Status<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p></div><h3 id="classic-status-page" tabindex="-1">Classic Status Page <a class="header-anchor" href="#classic-status-page" aria-label="Permalink to &quot;Classic Status Page&quot;">​</a></h3><p>This page shows information about the currently installed version.</p><div class="admonition xdripitem"><p class="admonition-title"><div style="background-color:DodgerBlue;color:white;text-align:center;">  Classic Status Page </div></p><p> Version: a2bbca9-2024.11.26</p></div><p>Version information allows you to quickly <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">find the matching release or pre-release</a>. Before the version date you&#39;ll see the build version.</p><p>Any version name that shows additional information, like debug, dev, a smartwatch name, carelink, is a <a href="./../install/download.html#forked-versions">forked version release</a> of xDrip and might not contain all the latest functions of the released app (but probably some extra).</p><p>On this page you&#39;ll find the data source type (the one you selected to receive your BG values).</p><div class="admonition xdripitem"><p class="admonition-title">Data Source:</p></div><p>Next line shows the xDrip database size: the amount of memory it uses in your phone.</p><div class="admonition xdripitem"><p class="admonition-title">Database size:</p></div><p>In the case of a physical sensor, after the data source type, you&#39;ll see the name of the actual Bluetooth device connected to xDrip. You can also see the connection status; keep in mind some sensors only connect for a short amount of time every 5 minutes and Not connected might not be an actual issue.</p><div class="admonition xdripitem"><p class="admonition-title">Bluetooth Device:</p></div><div class="admonition xdripitem"><p class="admonition-title">Connection Status:</p></div><div class="admonition xdripitem"><p class="admonition-title">Sensor Start:</p></div><p>Since this page doesn&#39;t update automatically, you need to touch the rounded arrows to refresh it.</p><img src="'+i+'" style="zoom:75%;"><h4 id="restart-collector-forget-device" tabindex="-1">Restart collector - Forget device <a class="header-anchor" href="#restart-collector-forget-device" aria-label="Permalink to &quot;Restart collector - Forget device&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><span style="background-color:white;color:black;"> RESTART COLLECTOR </span> <span style="background-color:white;color:black;"> FORGET DEVICE </span></p></div><p>Restart collector will restart xDrip internal collector mechanism. The effect depends on the data source.</p><p>Forget device will only have effect when xDrip is connected through Bluetooth to a device.<br> The device will be disconnected and you will need to scan Bluetooth from the main menu to recover the connection.</p><h3 id="advanced-status-page" tabindex="-1">Advanced status page <a class="header-anchor" href="#advanced-status-page" aria-label="Permalink to &quot;Advanced status page&quot;">​</a></h3><p>Most data sources will have an advanced status tab. Swipe your finger on the screen towards the left to display it.</p><img src="'+c+'" style="zoom:75%;"><h5 id="buggy-samsung" tabindex="-1">Buggy Samsung <a class="header-anchor" href="#buggy-samsung" aria-label="Permalink to &quot;Buggy Samsung&quot;">​</a></h5><p>Renamed to Buggy Handset since other devices present this non-compliance.</p><h5 id="buggy-handset" tabindex="-1">Buggy Handset <a class="header-anchor" href="#buggy-handset" aria-label="Permalink to &quot;Buggy Handset&quot;">​</a></h5><p>This is not an error, but just the fact xDrip is <a href="https://github.com/NightscoutFoundation/xDrip/issues/435" target="_blank" rel="noreferrer">correcting</a> an Android non-compliance of some devices.<br> It is recommended to <a href="./../use/misc.html#wake-workarounds">enable it</a> when experiencing data loss.</p><img src="'+s+'" style="zoom:75%;"><h5 id="slowest-wake-up" tabindex="-1">Slowest wake-up <a class="header-anchor" href="#slowest-wake-up" aria-label="Permalink to &quot;Slowest wake-up&quot;">​</a></h5><p>It is information on when xDrip received data against the expected time. Seconds are acceptable but minutes might be the sign of a connectivity issue.</p><img src="'+r+'" style="zoom:75%;"><h4 id="g6-g7-1-and-1" tabindex="-1">G6, G7, 1 and 1+ <a class="header-anchor" href="#g6-g7-1-and-1" aria-label="Permalink to &quot;G6, G7, 1 and 1+&quot;">​</a></h4><p>See the dedicated pages for <a href="./g6.html">G6/ONE</a> and <a href="./g7.html">G7/ONE+</a>. More details on connectivity <a href="https://navid200.github.io/xDrip/docs/Connectivity-troubleshoot.html" target="_blank" rel="noreferrer">here</a>.</p><h4 id="libre-bluetooth" tabindex="-1">Libre Bluetooth <a class="header-anchor" href="#libre-bluetooth" aria-label="Permalink to &quot;Libre Bluetooth&quot;">​</a></h4><p>If using a bridge, see the dedicated page <a href="./librebridge.html">here</a>.</p><p>If using a Libre 2 directly (i.e. without a bridge), see the dedicated page <a href="./libre2direct.html">here</a>.</p><h4 id="xdrip-sync-follower" tabindex="-1">xDrip Sync Follower <a class="header-anchor" href="#xdrip-sync-follower" aria-label="Permalink to &quot;xDrip Sync Follower&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Work in progress</p><p>In July 2024, Google shut down the deprecated <a href="https://firebase.google.com/docs/cloud-messaging/migrate-v1" target="_blank" rel="noreferrer">Firebase API</a> xDrip used for xDrip Sync.<br> Update xDrip to a version from <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.07.23" target="_blank" rel="noreferrer">July 23rd 2024</a>.</p></div><p>xDrip follower is really simple to <a href="./../use/syncsetup.html">set up</a>. If you have issues with it, most of the time it&#39;s either a network connection or Google Play services issues.<br> Having also <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> available as a backup follower solution is recommended when troubleshooting or following a child.</p><img src="'+n+'" style="zoom:75%;"><p>Followers will add up in the list when identified; if you remove a follower it might take some time before it&#39;s actually removed from the list.</p><p>For initial setup problems check <a href="./../install/xdripfollower.html">here</a>.</p><h4 id="nightscout-follower" tabindex="-1">Nightscout Follower <a class="header-anchor" href="#nightscout-follower" aria-label="Permalink to &quot;Nightscout Follower&quot;">​</a></h4><p>Advanced status page will show the activity when downloading from Nightscout. If no data is available, make sure you have current BG values in Nightscout.</p><p>In case of download failure, if your Nightscout site is regularly updated by the master device and you see NS download errors, this might be due to network problems. Disable Wi-Fi or SIM data and then try the other way round to exclude this problem.</p><p>If it&#39;s never been working, make sure you have <a href="./../install/nightscoutfollower.html">set up</a> your follower URL correctly.</p><img src="'+l+'" style="zoom:75%;"><p>Old Android versions might use expired certificates and hence prevent Nightscout follower function. There is no workaround.</p><img src="'+d+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',54)])])}const P=h(g,[["render",f]]);export{N as __pageData,P as default};
